const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Northern part of Lake Eyre (approximate polygon)
    const geometry = ee.Geometry.Polygon(
      [[[137.2, -28.3],
        [137.6, -28.3],
        [137.6, -28.6],
        [137.2, -28.6],
        [137.2, -28.3]]]);

    // Define specific date ranges for comparison
    const dateStart1 = '2025-06-15'; // Around June 20, 2025
    const dateEnd1 = '2025-06-25';

    const dateStart2 = '2025-09-10'; // Around September 15, 2025
    const dateEnd2 = '2025-09-20';

    const SCALE = 30; // Use a reasonable scale to avoid memory issues and get a general area. Sentinel-2 is 10m, but 30m is fine for area calculation.

    // Function to mask clouds in Sentinel-2 SR data
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000); // Scale to SR values [0,1]
    }

    // Function to calculate MNDWI and create water mask
    function calculateMNDWI(image) {
      const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green (B3), SWIR1 (B11)
      const water = mndwi.gt(0.1).rename('water'); // Threshold MNDWI to get water (adjust threshold if needed)
      return image.addBands(mndwi).addBands(water);
    }

    // Function to get image collection and process
    async function getWaterExtent(startDate, endDate, periodName) {
      let collection = ee.ImageCollection('COPERNICUS/S2_SR')
                           .filterDate(startDate, endDate)
                           .filterBounds(geometry)
                           .map(maskS2clouds)
                           .map(calculateMNDWI);

      let collectionSize = collection.size().getInfo();
      if (collectionSize === 0) {
        console.log(`No Sentinel-2 SR images found for ${periodName} (${startDate} - ${endDate}). Trying a wider range.`);
        // Fallback: Widen the date range
        let widenedStartDate = ee.Date(startDate).advance(-10, 'day');
        let widenedEndDate = ee.Date(endDate).advance(10, 'day');
        collection = ee.ImageCollection('COPERNICUS/S2_SR')
                         .filterDate(widenedStartDate, widenedEndDate)
                         .filterBounds(geometry)
                         .map(maskS2clouds)
                         .map(calculateMNDWI);
        collectionSize = collection.size().getInfo();
      }

      if (collectionSize === 0) {
        console.log(`No images found for ${periodName} even after widening dates (${startDate} - ${endDate}).`);
        return { totalWaterPixels: null, cloudCover: null, imageCount: 0 };
      }

      // Mosaic and clip to geometry
      const image = collection.median().clip(geometry);

      // Get mean cloud cover (from QA60 original band)
      const cloudCoverMean = ee.ImageCollection('COPERNICUS/S2_SR')
                               .filterDate(startDate, endDate)
                               .filterBounds(geometry)
                               .select('QA60')
                               .mosaic()
                               .reduceRegion({
                                 reducer: ee.Reducer.mean(),
                                 geometry: geometry,
                                 scale: SCALE,
                                 maxPixels: 1e9
                               })
                               .get('QA60').getInfo();

      const cloudPerc = cloudCoverMean ? (cloudCoverMean & (1 << 10) || cloudCoverMean & (1 << 11)) ? 'High' : 'Low' : 'N/A';
      console.log(`${periodName} Images: ${collectionSize}, Cloud (QA60): ${cloudPerc}`);

      const waterMask = image.select('water');
      const totalWaterPixels = await waterMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: SCALE,
        maxPixels: 1e9
      }).get('water').getInfo();

      return {
        totalWaterPixels: totalWaterPixels,
        cloudCover: cloudPerc,
        imageCount: collectionSize
      };
    }

    // Get water extent for period 1
    const result1 = await getWaterExtent(dateStart1, dateEnd1, 'Period 1 (June)');

    // Get water extent for period 2
    const result2 = await getWaterExtent(dateStart2, dateEnd2, 'Period 2 (Sept)');

    // Check for C1 (Empty Collection)
    if (result1.imageCount === 0 || result2.imageCount === 0) {
      console.log("Empty Collection (No images found in date/location for one or both comparison points).");
      console.log("C1");
      return;
    }

    // Check for C2 (No Valid Pixels after masking)
    if (result1.totalWaterPixels === 0 && result2.totalWaterPixels === 0) {
      console.log("No valid water pixels detected in either period after processing.");
      console.log("C2");
      return;
    }
    if (result1.totalWaterPixels === null || result2.totalWaterPixels === null) {
      console.log("Calculation Failure (Result is None).");
      console.log("C3");
      return;
    }

    // Calculate actual area (pixel count * pixel area)
    const pixelArea = SCALE * SCALE; // in square meters
    const waterArea1 = result1.totalWaterPixels * pixelArea / 1e6; // in square kilometers
    const waterArea2 = result2.totalWaterPixels * pixelArea / 1e6; // in square kilometers

    console.log(`June 20, 2025 water extent: ${waterArea1.toFixed(2)} sq km`);
    console.log(`Sept 15, 2025 water extent: ${waterArea2.toFixed(2)} sq km`);

    // 5. Validation & Final Answer
    if (waterArea2 > waterArea1) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // General error/syntax/memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
